import random
secret = random.randint(1, 100)
while True:
    guess = int(input('Enter your guess (1-100): '))
    if guess < secret:
        print('Too low!')
    elif guess > secret:
        print('Too high!')
    else:
        print('Congratulations! You guessed it.')
        break

attempts = 0
while True:
    try:
        guess = int(input('Enter your guess (1-100): '))
    except ValueError:
        print('Please enter a valid number.')
        continue
    attempts += 1
    if guess < secret:
        print('Too low!')
    elif guess > secret:
        print('Too high!')
    else:
        print(f'Correct! You needed {attempts} attempts.')
        break
